// Build the cleared record for every row the pre-filter marked junk_domain.
const ne = (v) => v !== undefined && v !== null && String(v).trim() !== '';

const out = [];
let jobTitleCases = 0, mismatchCases = 0;

for (const item of $input.all()) {
  const r = item.json;
  if (String(r.sendability || '').toLowerCase() !== 'junk_domain') continue;
  if (!ne(r.provider_id)) continue;
  if (String(r.enriched_status || '') === 'junk_cleared') continue;   // already done

  const badEmail = String(r.email || '').trim();
  const badDomain = (badEmail.split('@')[1] || '').toLowerCase();
  const reason = String(r.email_check_result || '');

  if (/job title/i.test(reason)) jobTitleCases++;
  else mismatchCases++;

  // Preserve what we remove.
  const prior = String(r.email_candidates || '');
  const preserved = ('CLEARED: ' + badEmail + (prior ? ' | ' + prior : '')).slice(0, 900);

  const rec = {
    provider_id: r.provider_id,
    email: '',
    email_source: '',
    email_candidates: preserved,
    email_confidence: '',
    email_verified: '',
    sendability: '',
    email_check_result: '',
    email_verified_at: '',
    enriched_status: 'junk_cleared',
    enriched_at: new Date().toISOString()
  };

  // Only blank the domain if it was the fabricated one.
  const currentDomain = String(r.company_domain || '').toLowerCase();
  if (currentDomain && badDomain && currentDomain === badDomain) {
    rec.company_domain = '';
    rec.domain_verified = '';
  }

  out.push({ json: rec });
}

console.log(`Junk cleanup: ${out.length} rows to clear (${jobTitleCases} job-title companies, ${mismatchCases} domain mismatches)`);
return out;

let rows = [];
try { rows = $('Select Junk Rows').all().map(i => i.json); } catch (e) {}
return [{ json: { run_id: $execution.id, finished_at: new Date().toISOString(), rows_cleared: rows.length, sample: rows.slice(0, 5).map(r => r.provider_id) }}];
